        "script": "const tier = $vars.start.output.customerTier;
const isDown = $vars.start.output.productionDown;
const hasWorkaround = $vars.start.output.workaroundAvailable;
const impact = $vars.start.output.businessImpact;
const corrId = $vars.start.output.correlationId;

const isPremiumTier = tier === 'Enterprise' || tier === 'Premier';

let severity;
if (isDown && isPremiumTier) {
  severity = 'Critical';
} else if (isDown || (isPremiumTier && impact === 'High')) {
  severity = 'High';
} else if (!hasWorkaround && impact === 'Medium') {
  severity = 'Medium';
} else {
  severity = 'Low';
}

const engineeringNeeded = severity === 'Critical' || severity === 'High';

let responseMode;
if (severity === 'Critical') {
  responseMode = 'Immediate';
} else if (severity === 'High') {
  responseMode = 'SameDay';
} else if (severity === 'Medium') {
  responseMode = 'NextBusinessDay';
} else {
  responseMode = 'Standard';
}

const caseKey = 'CASE-' + corrId;

return { severity, engineeringNeeded, responseMode, caseKey };"

